const p = $json.body ?? $json;

const req = ["store_id", "periodo", "tipo_de_oportunidade", "metricas", "pergunta_de_analise"];
const faltando = req.filter((k) => p[k] === undefined || p[k] === null);
if (faltando.length) {
  throw new Error("Payload inválido do RevenuePilot. Campos ausentes: " + faltando.join(", "));
}

const num = (v) => (v === null || v === undefined || v === "" ? null : Number(v));
const m = p.metricas ?? {};
const evidencias = Array.isArray(p.evidencias) ? p.evidencias : [];

return [{ json: {
  store_id: String(p.store_id),
  tipo_de_oportunidade: String(p.tipo_de_oportunidade),
  periodo: { inicio: p.periodo.inicio, fim: p.periodo.fim, comparacao: p.periodo.comparacao },
  moeda: m.moeda ?? "BRL",
  metricas: {
    receita_atual: num(m.receita_atual), receita_anterior: num(m.receita_anterior),
    pedidos_atual: num(m.pedidos_atual), pedidos_anterior: num(m.pedidos_anterior),
    conversao_atual: num(m.conversao_atual), conversao_anterior: num(m.conversao_anterior),
    investimento_midia: num(m.investimento_midia), cac_atual: num(m.cac_atual),
    cac_anterior: num(m.cac_anterior), roas_atual: num(m.roas_atual),
    impacto_estimado: num(m.impacto_estimado),
  },
  evidencias_texto: evidencias.map((e) => `${e.label}: ${e.value}`).join("\\n"),
  pergunta_de_analise: String(p.pergunta_de_analise),
}}];

parameters.text:
=Você é analista de crescimento de e-commerce DTC. Analise SOMENTE os dados abaixo, sem inventar métricas ou integrações. Responda em português.

Loja: {{ $json.store_id }}
Tipo de oportunidade: {{ $json.tipo_de_oportunidade }}
Período: {{ $json.periodo.inicio }} a {{ $json.periodo.fim }} (comparado com {{ $json.periodo.comparacao }})
Moeda: {{ $json.moeda }}
Métricas: {{ JSON.stringify($json.metricas) }}
Evidências:
{{ $json.evidencias_texto }}

Pergunta: {{ $json.pergunta_de_analise }}

Responda EXATAMENTE com um único objeto JSON contendo estas 8 chaves: diagnostico (string com o que os dados mostram, incluindo números), hipotese (string com a causa mais provável), acao_recomendada (string com próximo passo executável), impacto_estimado (string com premissa e cálculo, nunca fato), nivel_de_confianca (exatamente baixo, medio ou alto), dados_utilizados (array de strings), riscos (array de strings) e metricas_de_sucesso (array de strings). Liste explicitamente os dados usados e os riscos. Se os dados não sustentarem uma conclusão, use nivel_de_confianca baixo. Não inclua markdown nem texto fora do JSON.

