function textoBruto(v) {
  if (typeof v === "string") return v;
  if (Array.isArray(v)) return v.map((x) => x?.text ?? x?.content ?? "").join("");
  return JSON.stringify(v);
}
function limpar(v) {
  return v.trim().replace(/^```json\\s*/i, "").replace(/^```\\s*/i, "").replace(/```$/i, "").trim();
}
const obrigatorios = ["diagnostico", "hipotese", "acao_recomendada", "impacto_estimado", "nivel_de_confianca", "dados_utilizados", "riscos", "metricas_de_sucesso"];
const lista = (v) => Array.isArray(v) ? v.map(String) : (v === undefined || v === null || v === "" ? [] : [String(v)]);
const niveis = ["baixo", "medio", "alto"];

return $input.all().map((item) => {
  const bruto = item.json.output ?? item.json.text ?? item.json.message?.content ?? item.json;
  let dados;
  try { dados = typeof bruto === "string" ? JSON.parse(limpar(bruto)) : bruto; }
  catch (e) { throw new Error(`Resposta da IA não é um JSON válido. Conteúdo: ${textoBruto(bruto).slice(0, 500)}`); }
  const faltando = obrigatorios.filter((k) => dados?.[k] === undefined);
  if (faltando.length) throw new Error("Resposta fora do contrato. Ausentes: " + faltando.join(", "));
  const nivel = niveis.includes(String(dados.nivel_de_confianca).toLowerCase()) ? String(dados.nivel_de_confianca).toLowerCase() : "baixo";
  return { json: {
    diagnostico: String(dados.diagnostico), hipotese: String(dados.hipotese), acao_recomendada: String(dados.acao_recomendada),
    impacto_estimado: String(dados.impacto_estimado), nivel_de_confianca: nivel,
    dados_utilizados: lista(dados.dados_utilizados), riscos: lista(dados.riscos), metricas_de_sucesso: lista(dados.metricas_de_sucesso),
  }};
});
